    protected function doInsert(PropelPDO $con)
    {
        $this->modifiedColumns[] = ServicioPeer::SERVICIO_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(ServicioPeer::SERVICIO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . ServicioPeer::SERVICIO_ID . ')');
        }
        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ServicioPeer::SERVICIO_ID);
        $pk = BasePeer::doInsert($criteria, $con);
        $this->setServicioId($pk);  //[IMV] update autoincrement primary key
        $this->setNew(false);
    }

